import type { MetadataRoute } from "next";

/**
 * PWA manifest (Mobile Phase 1) — served by Next at
 * /manifest.webmanifest and linked automatically.
 *
 * Icons are SVG (a white "Z" on the brand teal) — install prompts in
 * Chrome/Android accept SVG icons, and the file is text so it travels
 * with the source. Matching PNGs (192/512/maskable + apple-touch) are
 * generated by scripts/generate-icons.mjs into public/icons/ for
 * platforms that require raster icons (notably iOS home-screen).
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Z-clean — Laundry & Dry Cleaning",
    short_name: "Z-clean",
    description:
      "Laundry and dry-cleaning with doorstep pickup and delivery in Bokaro Steel City. Book a pickup, track your order, pay on delivery.",
    start_url: "/",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    background_color: "#ffffff",
    theme_color: "#22786d",
    icons: [
      {
        src: "/icons/icon.svg",
        sizes: "any",
        type: "image/svg+xml",
        purpose: "any",
      },
      {
        src: "/icons/icon.svg",
        sizes: "any",
        type: "image/svg+xml",
        purpose: "maskable",
      },
    ],
  };
}
